'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useId, useMemo, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { RefreshCwIcon } from '@/registry/ndeko/lib/icons';
import { Input } from '@/registry/ndeko/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/registry/ndeko/ui/select';
import { Switch } from '@/registry/ndeko/ui/switch';

import { ActionButton, useTimedAction } from './_parts/action-button';
import { CopyButton } from './_parts/copy-button';
import {
  ModalDescription,
  ModalHeader,
  ModalPreview,
  ModalTitle,
} from './_parts/modal-frame';
import { SWAP_TRANSITION, swapVariantsOf } from './_parts/motion';
import { TEAM_NAME } from './_parts/people';
import { Swap } from './_parts/swap';

type ExpiryValue = '1' | '7' | '30' | 'never';

type ExpiryOption = { value: ExpiryValue; label: string; line: string };

type InviteLink = { token: string; code: string[] };

const LINK_BASE = 'https://lattice.example/join/';

const LINKS: InviteLink[] = [
  { token: '7q4m-92kd-h3xa', code: ['7Q4M', '92KD'] },
  { token: 'p5zr-wb81-c6tn', code: ['P5ZR', 'WB81'] },
  { token: 'k2vf-ye47-m9qd', code: ['K2VF', 'YE47'] },
];

const EXPIRY_OPTIONS: ExpiryOption[] = [
  { value: '1', label: '1 day', line: 'The link stops working tomorrow' },
  { value: '7', label: '7 days', line: 'The link stops working on Nov 12' },
  { value: '30', label: '30 days', line: 'The link stops working on Dec 5' },
  { value: 'never', label: 'Never', line: 'The link works until you reset it' },
];

const QR_MODULES = 25;

const QR_QUIET_ZONE = 2;

const FINDER_SIZE = 7;

const QR_VIEWBOX_SIZE = QR_MODULES + QR_QUIET_ZONE * 2;

function hashOf(text: string) {
  let hash = 2166136261;
  for (const character of text) {
    const code = character.charCodeAt(0);
    hash ^= code;
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function randomStreamOf(seed: number) {
  let state = seed || 1;
  return function next() {
    state ^= state << 13;
    state ^= state >>> 17;
    state ^= state << 5;
    const unsigned = state >>> 0;
    return unsigned / 4294967296;
  };
}

function finderOriginOf(row: number, column: number) {
  const far = QR_MODULES - FINDER_SIZE;
  const isTop = row < FINDER_SIZE + 1;
  const isLeft = column < FINDER_SIZE + 1;
  const isBottom = row >= far - 1;
  const isRight = column >= far - 1;
  const isTopLeft = isTop && isLeft;
  const isTopRight = isTop && isRight;
  const isBottomLeft = isBottom && isLeft;
  if (isTopLeft) {
    return { row: 0, column: 0 };
  }
  if (isTopRight) {
    return { row: 0, column: far };
  }
  if (isBottomLeft) {
    return { row: far, column: 0 };
  }
  return null;
}

function isFinderDark(localRow: number, localColumn: number) {
  const isInside = localRow >= 0 && localRow < FINDER_SIZE;
  const isInsideColumn = localColumn >= 0 && localColumn < FINDER_SIZE;
  if (!isInside || !isInsideColumn) {
    return false;
  }
  const isEdgeRow = localRow === 0 || localRow === FINDER_SIZE - 1;
  const isEdgeColumn = localColumn === 0 || localColumn === FINDER_SIZE - 1;
  const isCoreRow = localRow >= 2 && localRow <= 4;
  const isCoreColumn = localColumn >= 2 && localColumn <= 4;
  const isEdge = isEdgeRow || isEdgeColumn;
  const isCore = isCoreRow && isCoreColumn;
  return isEdge || isCore;
}

/**
 * Draws a code with the look of a QR code, derived from the link so it changes when the link does. It is not a
 * scannable QR encoding: plug a QR encoder in to make it one.
 */
function qrPathOf(text: string) {
  const random = randomStreamOf(hashOf(text));
  const segments: string[] = [];
  for (let row = 0; row < QR_MODULES; row += 1) {
    for (let column = 0; column < QR_MODULES; column += 1) {
      const origin = finderOriginOf(row, column);
      let isDark = random() > 0.52;
      if (origin) {
        const localRow = row - origin.row;
        const localColumn = column - origin.column;
        isDark = isFinderDark(localRow, localColumn);
      }
      if (!isDark) {
        continue;
      }
      const x = column + QR_QUIET_ZONE;
      const y = row + QR_QUIET_ZONE;
      segments.push(`M${x} ${y}h1v1h-1z`);
    }
  }
  return segments.join('');
}

function isExpiryValue(value: unknown): value is ExpiryValue {
  return EXPIRY_OPTIONS.some((option) => option.value === value);
}

function approvalLineOf(needsApproval: boolean) {
  if (needsApproval) {
    return 'They wait in Requests until a manager lets them in';
  }
  return `They join the ${TEAM_NAME} team as members right away`;
}

function QrCode({ url }: { url: string }) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion, 'label');
  const path = useMemo(() => qrPathOf(url), [url]);
  const viewBox = `0 0 ${QR_VIEWBOX_SIZE} ${QR_VIEWBOX_SIZE}`;

  return (
    <div className='bg-card hairline-ring ring-border relative size-40 overflow-hidden rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
      <AnimatePresence initial={false}>
        <motion.svg
          key={url}
          viewBox={viewBox}
          role='img'
          aria-label='Illustrative code of the invite link'
          shapeRendering='crispEdges'
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
          className='text-foreground absolute inset-0 size-full'
        >
          <path d={path} fill='currentColor' />
        </motion.svg>
      </AnimatePresence>
    </div>
  );
}

function InviteLinkContent() {
  const [linkIndex, setLinkIndex] = useState(0);
  const [expiry, setExpiry] = useState<ExpiryValue>('7');
  const [needsApproval, setNeedsApproval] = useState(false);
  const resetAction = useTimedAction();
  const linkFieldId = useId();
  const expiryLabelId = useId();
  const approvalId = useId();
  const link = LINKS[linkIndex];
  const url = `${LINK_BASE}${link.token}`;
  const codeText = link.code.join('-');
  const codeKey = link.code.join('');
  const expiryOption = EXPIRY_OPTIONS.find((option) => option.value === expiry);
  const expiryLine = expiryOption?.line ?? '';
  const approvalLine = approvalLineOf(needsApproval);

  function changeExpiry(value: unknown) {
    if (isExpiryValue(value)) {
      setExpiry(value);
    }
  }

  function commitReset() {
    setLinkIndex((previous) => {
      const next = previous + 1;
      return next % LINKS.length;
    });
  }

  function resetLink() {
    resetAction.run(commitReset);
  }

  return (
    <div className='grid gap-6 sm:grid-cols-[minmax(0,1fr)_13rem]'>
      <div className='flex min-w-0 flex-col gap-5'>
        <ModalHeader>
          <ModalTitle>Invite with a link</ModalTitle>
          <ModalDescription>
            {`Anyone with this link can join the ${TEAM_NAME} team`}
          </ModalDescription>
        </ModalHeader>
        <div className='flex flex-col gap-1.5'>
          <label htmlFor={linkFieldId} className='text-[13px] font-medium'>
            Invite link
          </label>
          <div className='flex items-center gap-2'>
            <Input
              id={linkFieldId}
              readOnly
              value={url}
              className='text-muted-foreground min-w-0 flex-1 truncate'
            />
            <CopyButton
              text={url}
              label='Copy'
              size='default'
              announcement='Invite link copied'
            />
          </div>
        </div>
        <div className='flex flex-col gap-1.5'>
          <div className='flex items-center justify-between gap-3'>
            <span id={expiryLabelId} className='text-[13px] font-medium'>
              Link expires after
            </span>
            <Select
              items={EXPIRY_OPTIONS}
              value={expiry}
              onValueChange={changeExpiry}
            >
              <SelectTrigger aria-labelledby={expiryLabelId} className='w-32'>
                <SelectValue />
              </SelectTrigger>
              <SelectContent align='end'>
                {EXPIRY_OPTIONS.map((option) => (
                  <SelectItem key={option.value} value={option.value}>
                    {option.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <Swap
            swapKey={expiryLine}
            kind='label'
            className='text-muted-foreground flex text-xs'
          >
            {expiryLine}
          </Swap>
        </div>
        <div className='flex items-start justify-between gap-3'>
          <div className='flex min-w-0 flex-col gap-0.5'>
            <label htmlFor={approvalId} className='text-[13px] font-medium'>
              Approve people who join
            </label>
            <Swap
              swapKey={approvalLine}
              kind='label'
              className='text-muted-foreground flex min-w-0 text-xs'
              contentClassName='max-w-full min-w-0 whitespace-normal'
            >
              {approvalLine}
            </Swap>
          </div>
          <Switch
            id={approvalId}
            checked={needsApproval}
            onCheckedChange={setNeedsApproval}
          />
        </div>
        <div className='flex items-center gap-2'>
          <ActionButton
            variant='outline'
            size='sm'
            state={resetAction.state}
            onClick={resetLink}
            idleIcon={<RefreshCwIcon />}
            labels={{
              idle: 'Reset link',
              working: 'Resetting',
              done: 'New link ready',
            }}
          />
          <p className='text-muted-foreground text-xs'>
            The old link and code stop working
          </p>
        </div>
      </div>
      <div className='bg-foreground/[0.03] flex flex-col items-center gap-4 rounded-xl px-4 py-5 text-center'>
        <div className='flex flex-col gap-0.5'>
          <p className='text-[13px] font-medium'>Scan to join</p>
          <p className='text-muted-foreground text-xs'>
            Opens the invite on a phone
          </p>
        </div>
        <QrCode url={url} />
        <p className='text-muted-foreground text-xs'>or enter the code</p>
        <div className='flex items-center gap-1.5'>
          <Swap swapKey={codeKey} kind='label' className='gap-1'>
            {link.code.map((part) => (
              <span
                key={part}
                className='keycap-3d rounded-md px-2 py-1 font-mono text-[13px] font-medium tabular-nums'
              >
                {part}
              </span>
            ))}
          </Swap>
          <CopyButton
            text={codeText}
            variant='ghost'
            size='icon-sm'
            aria-label='Copy the invite code'
            announcement='Invite code copied'
            className='text-muted-foreground'
          />
        </div>
      </div>
    </div>
  );
}

export default function Modal03() {
  return (
    <ModalPreview triggerLabel='Open the invite link dialog' size='xl'>
      <InviteLinkContent />
    </ModalPreview>
  );
}

'use client';

import { useEffect, useRef, useState } from 'react';

import { CheckIcon, LoaderCircleIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';

import { Swap } from './swap';

export type ActionState = 'idle' | 'working' | 'done';

export type ActionLabels = Record<ActionState, string>;

const WORKING_MS = 800;

const DONE_MS = 1600;

/** The life of an action that takes a moment: working, then done for a beat, then ready again. The change is committed when the work ends. */
export function useTimedAction() {
  const [state, setState] = useState<ActionState>('idle');
  const commitRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    if (state === 'working') {
      const timeout = window.setTimeout(() => {
        const commit = commitRef.current;
        commitRef.current = null;
        if (commit) {
          commit();
        }
        setState('done');
      }, WORKING_MS);
      return () => window.clearTimeout(timeout);
    }
    if (state === 'done') {
      const timeout = window.setTimeout(() => {
        setState('idle');
      }, DONE_MS);
      return () => window.clearTimeout(timeout);
    }
  }, [state]);

  function run(commit: () => void) {
    if (state !== 'idle') {
      return;
    }
    commitRef.current = commit;
    setState('working');
  }

  const isBusy = state !== 'idle';

  return { state, run, isBusy };
}

function iconOf(state: ActionState, idleIcon: React.ReactNode) {
  if (state === 'working') {
    return <LoaderCircleIcon className='animate-spin' />;
  }
  if (state === 'done') {
    return <CheckIcon />;
  }
  return idleIcon;
}

type ActionButtonProps = Omit<ButtonProps, 'children'> & {
  state: ActionState;
  labels: ActionLabels;
  idleIcon?: React.ReactNode;
};

/** One button that becomes its next state: its icon swaps, its label crossfades and its width follows the new label. */
export function ActionButton({
  state,
  labels,
  idleIcon,
  ...props
}: ActionButtonProps) {
  const icon = iconOf(state, idleIcon);
  const hasIcon = Boolean(icon);
  const label = labels[state];
  const isWorking = state === 'working';
  const isDone = state === 'done';

  return (
    <>
      <Button aria-busy={isWorking} {...props}>
        {hasIcon && <Swap swapKey={state}>{icon}</Swap>}
        <AnimatedSize axis='width' as='span'>
          <Swap swapKey={label} kind='label'>
            {label}
          </Swap>
        </AnimatedSize>
      </Button>
      <span className='sr-only' role='status'>
        {isDone && labels.done}
      </span>
    </>
  );
}

'use client';

import { useEffect, useState } from 'react';

import { CheckIcon, CopyIcon, LinkIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';

import { Swap } from './swap';

const COPIED_RESET_MS = 1600;

/** Copies a text and says so for a moment. */
export function useCopy(text: string) {
  const [isCopied, setIsCopied] = useState(false);

  useEffect(() => {
    if (!isCopied) {
      return;
    }
    const timeout = window.setTimeout(() => {
      setIsCopied(false);
    }, COPIED_RESET_MS);
    return () => window.clearTimeout(timeout);
  }, [isCopied]);

  async function copy() {
    try {
      await navigator.clipboard.writeText(text);
      setIsCopied(true);
    } catch {
      setIsCopied(false);
    }
  }

  return { isCopied, copy };
}

type CopyGlyph = 'copy' | 'link';

function glyphOf(isCopied: boolean, glyph: CopyGlyph) {
  if (isCopied) {
    return <CheckIcon className='text-success-foreground' />;
  }
  if (glyph === 'link') {
    return <LinkIcon />;
  }
  return <CopyIcon />;
}

function labelOf(isCopied: boolean, label: string, copiedLabel: string) {
  if (isCopied) {
    return copiedLabel;
  }
  return label;
}

type CopyButtonProps = Omit<ButtonProps, 'children' | 'onClick'> & {
  text: string;
  /** Visible label. Leave it out for an icon button, and give `aria-label` instead. */
  label?: string;
  copiedLabel?: string;
  /** Announced once the text is on the clipboard. */
  announcement: string;
  glyph?: CopyGlyph;
};

/** A copy action whose icon becomes a check and whose label becomes Copied, then returns. */
export function CopyButton({
  text,
  label,
  copiedLabel = 'Copied',
  announcement,
  glyph = 'copy',
  variant = 'outline',
  size = 'sm',
  ...props
}: CopyButtonProps) {
  const { isCopied, copy } = useCopy(text);
  const icon = glyphOf(isCopied, glyph);
  const iconKey = String(isCopied);
  const hasLabel = Boolean(label);
  const shownLabel = labelOf(isCopied, label ?? '', copiedLabel);

  return (
    <>
      <Button variant={variant} size={size} onClick={copy} {...props}>
        <Swap swapKey={iconKey}>{icon}</Swap>
        {hasLabel && (
          <AnimatedSize axis='width' as='span'>
            <Swap swapKey={shownLabel} kind='label'>
              {shownLabel}
            </Swap>
          </AnimatedSize>
        )}
      </Button>
      <span className='sr-only' role='status'>
        {isCopied && announcement}
      </span>
    </>
  );
}

'use client';

import { createContext, useContext } from 'react';

import { SquareArrowOutUpRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogTitle,
  DialogTrigger,
} from '@/registry/ndeko/ui/dialog';

/** Where a modal's content is drawn: open in the page as a preview, or inside the real dialog. */
export type ModalHost = 'preview' | 'dialog';

const ModalHostContext = createContext<ModalHost>('preview');

export function useModalHost() {
  return useContext(ModalHostContext);
}

export type ModalSize = 'sm' | 'md' | 'lg' | 'xl';

const SIZE_CLASS: Record<ModalSize, string> = {
  sm: 'max-w-sm',
  md: 'max-w-md',
  lg: 'max-w-lg',
  xl: 'max-w-[44rem]',
};

const TITLE = 'text-lg leading-tight font-semibold text-balance';

const DESCRIPTION = 'text-muted-foreground text-[13px]';

const BODY = 'flex flex-col gap-4';

type ModalTextProps = { className?: string; children: React.ReactNode };

export function ModalTitle({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogTitle className={className}>{children}</DialogTitle>;
  }
  return <h2 className={cn(TITLE, className)}>{children}</h2>;
}

export function ModalDescription({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return (
      <DialogDescription className={className}>{children}</DialogDescription>
    );
  }
  return <p className={cn(DESCRIPTION, className)}>{children}</p>;
}

/** Leaves room for the dialog's close button, so the preview and the dialog lay out the same. */
export function ModalHeader({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div className={cn('flex flex-col gap-1.5 pr-8', className)} {...props} />
  );
}

export function ModalFooter({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div
      className={cn(
        'flex flex-col-reverse gap-2 sm:flex-row sm:items-center sm:justify-end',
        className
      )}
      {...props}
    />
  );
}

/** Closes the dialog. In the preview it stays a plain button that runs its own action, if any. */
export function ModalCloseButton({ children, ...props }: ButtonProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogClose render={<Button {...props} />}>{children}</DialogClose>;
  }
  return <Button {...props}>{children}</Button>;
}

type ModalPreviewProps = {
  /** The content, drawn twice: open in the page, and inside the dialog the trigger opens. */
  children: React.ReactNode;
  triggerLabel: string;
  size?: ModalSize;
  className?: string;
};

/** Shows a modal open and whole on the page, with a small trigger that opens the same content in the real dialog. */
export function ModalPreview({
  children,
  triggerLabel,
  size = 'md',
  className,
}: ModalPreviewProps) {
  const sizeClass = SIZE_CLASS[size];

  return (
    <div className='flex w-full flex-col items-center gap-4'>
      <ModalHostContext.Provider value='preview'>
        <div
          className={cn(
            'surface-raised w-full rounded-2xl p-6 text-left',
            sizeClass,
            className
          )}
        >
          <AnimatedSize contentClassName={BODY}>{children}</AnimatedSize>
        </div>
      </ModalHostContext.Provider>
      <Dialog>
        <DialogTrigger render={<Button variant='outline' size='sm' />}>
          <SquareArrowOutUpRightIcon />
          {triggerLabel}
        </DialogTrigger>
        <DialogContent className={cn(sizeClass, className)}>
          <ModalHostContext.Provider value='dialog'>
            {children}
          </ModalHostContext.Provider>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import type { Transition, Variants } from 'motion/react';

export const SWAP_TRANSITION: Transition = {
  duration: 0.15,
  ease: [0.2, 0, 0, 1],
};

const MORPH_SPRING: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const INSTANT: Transition = { duration: 0 };

const PRESENCE_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const PRESENCE_OUT: Transition = { duration: 0.14, ease: [0.23, 1, 0.32, 1] };

const ICON_SWAP: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const LABEL_SWAP: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, filter: 'blur(2px)' },
};

const FADE_SWAP: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const ROW_PRESENCE: Variants = {
  hidden: {
    height: 0,
    opacity: 0,
    overflow: 'hidden',
    transition: PRESENCE_OUT,
  },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: PRESENCE_IN,
    transitionEnd: { overflow: 'visible' },
  },
};

const ROW_FADE: Variants = {
  hidden: { opacity: 0, transition: PRESENCE_OUT },
  shown: { opacity: 1, transition: PRESENCE_IN },
};

const CHIP_PRESENCE: Variants = {
  hidden: { opacity: 0, scale: 0.9, transition: PRESENCE_OUT },
  shown: { opacity: 1, scale: 1, transition: PRESENCE_IN },
};

export type SwapKind = 'icon' | 'label';

export function swapVariantsOf(
  shouldReduceMotion: boolean | null,
  kind: SwapKind = 'icon'
) {
  if (shouldReduceMotion) {
    return FADE_SWAP;
  }
  if (kind === 'label') {
    return LABEL_SWAP;
  }
  return ICON_SWAP;
}

/** A row added to or removed from a list: its height opens or collapses, so the rows after it slide. */
export function rowVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return ROW_PRESENCE;
}

export function chipVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return CHIP_PRESENCE;
}

export function morphOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MORPH_SPRING;
}

export type Presence = 'tracking' | 'online' | 'away' | 'offline';

export type Person = {
  id: string;
  name: string;
  email: string;
  title: string;
  presence: Presence;
};

export const WORKSPACE_NAME = 'Lattice';

export const TEAM_NAME = 'Product';

export const PEOPLE: Person[] = [
  {
    id: 'amara',
    name: 'Amara Okafor',
    email: 'amara@lattice.example',
    title: 'Product designer',
    presence: 'tracking',
  },
  {
    id: 'lucas',
    name: 'Lucas Moreau',
    email: 'lucas@lattice.example',
    title: 'Engineering lead',
    presence: 'online',
  },
  {
    id: 'priya',
    name: 'Priya Raman',
    email: 'priya@lattice.example',
    title: 'Frontend engineer',
    presence: 'online',
